/// <summary>
/// returns InventTable record
/// </summary>
/// <returns>InventTable</returns>
public InventTable avainventTable()
{
    return InventTable::find(this.ItemId);
}

/// <summary>
/// Extension of method initFromPurchLine
/// </summary>
/// <param name = "_purchLine">PurchLine</param>
void  initFromPurchLine(PurchLine _purchLine)
{
    next initFromPurchLine(_purchLine);

    this.AVADeliveryName            = _purchLine.DeliveryName;
    this.AVADeliveryPostalAddress   = _purchLine.DeliveryPostalAddress;
}

/// <summary>
/// Returns delivery address
/// </summary>
/// <returns>LogisticsAddressing</returns>
display LogisticsAddressing avaDeliveryAddress()
{
    return DirUtility::replaceAddressTokenLanguage(LogisticsPostalAddress::findRecId(this.AVADeliveryPostalAddress),this.VendPackingSlipJour().LanguageId);
}
